-- FlowerDoro API initial schema and flower book seed.
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS users (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    device_id varchar(128) NOT NULL UNIQUE,
    display_name varchar(120) NOT NULL DEFAULT '',
    locale varchar(12) NOT NULL DEFAULT 'vi',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS user_settings (
    user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    work_minutes integer NOT NULL DEFAULT 30 CHECK (work_minutes > 0),
    break_minutes integer NOT NULL DEFAULT 5 CHECK (break_minutes > 0),
    clock_style varchar(40) NOT NULL DEFAULT 'gardenBed',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS gardens (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
    user_name varchar(120) NOT NULL DEFAULT 'You',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS flowers (
    id bigserial PRIMARY KEY,
    kind varchar(80) NOT NULL UNIQUE,
    sort_order integer NOT NULL UNIQUE,
    english_name varchar(120) NOT NULL,
    vietnamese_name varchar(120) NOT NULL,
    english_description text NOT NULL DEFAULT '',
    vietnamese_description text NOT NULL DEFAULT '',
    english_fact_1 text NOT NULL DEFAULT '',
    english_fact_2 text NOT NULL DEFAULT '',
    english_fact_3 text NOT NULL DEFAULT '',
    vietnamese_fact_1 text NOT NULL DEFAULT '',
    vietnamese_fact_2 text NOT NULL DEFAULT '',
    vietnamese_fact_3 text NOT NULL DEFAULT '',
    rarity varchar(40) NOT NULL DEFAULT 'common',
    asset_name varchar(120) NOT NULL DEFAULT '',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS focus_sessions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    started_at timestamptz NOT NULL,
    completed_at timestamptz,
    focus_minutes integer NOT NULL CHECK (focus_minutes > 0),
    rewarded boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS garden_flowers (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    garden_id uuid REFERENCES gardens(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    flower_kind varchar(80) NOT NULL REFERENCES flowers(kind) ON UPDATE CASCADE,
    focus_session_id uuid REFERENCES focus_sessions(id) ON DELETE SET NULL,
    focus_minutes integer NOT NULL CHECK (focus_minutes >= 30),
    earned_at timestamptz NOT NULL DEFAULT now(),
    created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE flowers ADD COLUMN IF NOT EXISTS sort_order integer;
ALTER TABLE flowers ADD COLUMN IF NOT EXISTS english_fact_1 text NOT NULL DEFAULT '';
ALTER TABLE flowers ADD COLUMN IF NOT EXISTS english_fact_2 text NOT NULL DEFAULT '';
ALTER TABLE flowers ADD COLUMN IF NOT EXISTS english_fact_3 text NOT NULL DEFAULT '';
ALTER TABLE flowers ADD COLUMN IF NOT EXISTS vietnamese_fact_1 text NOT NULL DEFAULT '';
ALTER TABLE flowers ADD COLUMN IF NOT EXISTS vietnamese_fact_2 text NOT NULL DEFAULT '';
ALTER TABLE flowers ADD COLUMN IF NOT EXISTS vietnamese_fact_3 text NOT NULL DEFAULT '';
ALTER TABLE garden_flowers ADD COLUMN IF NOT EXISTS garden_id uuid;

CREATE INDEX IF NOT EXISTS idx_garden_flowers_user_earned ON garden_flowers(user_id, earned_at DESC);
CREATE INDEX IF NOT EXISTS idx_garden_flowers_garden_earned ON garden_flowers(garden_id, earned_at DESC);
CREATE INDEX IF NOT EXISTS idx_garden_flowers_kind ON garden_flowers(flower_kind);
CREATE INDEX IF NOT EXISTS idx_focus_sessions_user_started ON focus_sessions(user_id, started_at DESC);

ON CONFLICT (kind) DO UPDATE SET
    sort_order = EXCLUDED.sort_order,
    english_name = EXCLUDED.english_name,
    vietnamese_name = EXCLUDED.vietnamese_name,
    english_description = EXCLUDED.english_description,
    vietnamese_description = EXCLUDED.vietnamese_description,
    english_fact_1 = EXCLUDED.english_fact_1,
    english_fact_2 = EXCLUDED.english_fact_2,
    english_fact_3 = EXCLUDED.english_fact_3,
    vietnamese_fact_1 = EXCLUDED.vietnamese_fact_1,
    vietnamese_fact_2 = EXCLUDED.vietnamese_fact_2,
    vietnamese_fact_3 = EXCLUDED.vietnamese_fact_3,
    rarity = EXCLUDED.rarity,
    asset_name = EXCLUDED.asset_name,
    updated_at = now();
